const canvas_orientation = randGen() > 0.5 ? 'vert' : 'horiz';
// const canvas_orientation = 'horiz'; console.log('warning canvas_orientation OVERRIDE!!!!!');
const canvas_orientation_multi = 1.5;
const canvas_orientation_multi_inv = 1 / 1.5;
window.$fxhashFeatures['Canvas orientation'] = canvas_orientation === 'vert' ? 'vertical' : 'horizontal';

let scale_multi = 1;
let user_input_locked = true;

//-----------------
const tree_tech_at_angle = randGen() > 0.5;
const tree_tech_amount_tapered = randGen() > 0.5;
window.$fxhashFeatures['Tech tree angled'] = tree_tech_at_angle === true ? 'Yes' : 'No';
window.$fxhashFeatures['Tech tree amount tapered'] = tree_tech_amount_tapered === true ? 'Yes' : 'No';

//-----------------
let force_palette_round = 0;
if( randGen() < 0.30 ){
	force_palette_round = getRandInt(2, 3);
}
// force_palette_round = 3;
window.$fxhashFeatures['Forced pallet limit'] = force_palette_round > 0 ? "Yes" : 'No';

//-----------------
let accelerate_vibrance = randGen() < 0.25 ? 1 : 0;
window.$fxhashFeatures['Accelerate gamma'] = accelerate_vibrance == 1 ? "Yes": 'No';

const tech_box_size = getRandInt(1, 3);

if( tech_box_size === 1){
    window.$fxhashFeatures['Tech tree parts size'] = 'Mini';
} else if( tech_box_size === 2){
    window.$fxhashFeatures['Tech tree parts size'] = 'Mid';
} else if( tech_box_size === 3){
    window.$fxhashFeatures['Tech tree parts size'] = 'Large';
}

